"id": "ComposeDetails",
"type": "object",
"description": "Used by various functions to represent the state of a message being composed. Note that functions using this type may have a partial implementation.",
"properties": {
  "additionalFccFolderId": {
    "min_manifest_version": 3,
    "$ref": "folders.MailFolderId",
    "description": "An additional fcc folder which can be selected while composing the message. Cleared when set to <var>null</var>. Has no effect when the message is saved as a draft or template; the additional copy is only created when the message is actually sent or queued for sending. The permission <permission>accountsRead</permission> is required to use this property.",
    "optional": "omit-key-if-missing"
  },
